sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    g_scratchpad.lock_field_mapping = false;
    g_scratchpad.lock_message = '';

    // If this Field Mapping belongs to a Sub Template
    if (!gs.nil(current.getValue('sub_template'))) {
        var st = new GlideRecord('x_2162040_documate_sub_template');

        if (st.get(current.getValue('sub_template'))) {
            var subState = st.getValue('state');

            if (subState == 'validated' || subState == 'complete') {
                g_scratchpad.lock_field_mapping = true;
                g_scratchpad.lock_message = 'This Field Mapping is read-only because the Sub Template is in ' + subState + ' state.';
                return;
            }
        }
    }

    // If this Field Mapping belongs directly to a Template
    if (!gs.nil(current.getValue('template'))) {
        var temp = new GlideRecord('x_2162040_documate_templates');

        if (temp.get(current.getValue('template'))) {
            var tempState = temp.getValue('state');

            if (tempState == 'validated' || tempState == 'published') {
                g_scratchpad.lock_field_mapping = true;
                g_scratchpad.lock_message = 'This Field Mapping is read-only because the Template is  in ' + tempState + ' state.';
                return;
            }
        }
    }

})(current, previous);
